import sys

def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    res = []
    def ok(p):
        return 1 <= len(p) <= 3 and (p == '0' or p[0] != '0') and int(p) <= 255
    for i in range(1, 4):
        for j in range(i + 1, i + 4):
            for k in range(j + 1, j + 4):
                if k < n and n - k <= 3:
                    parts = [s[:i], s[i:j], s[j:k], s[k:]]
                    if all(ok(p) for p in parts):
                        res.append('.'.join(parts))
    res.sort()
    print(len(res))
    for r in res:
        print(r)

