s = sys.stdin.read().split()[0]
n = len(s)
res = set()
for cuts in combinations(range(1, n), 3):
    c = (0,) + cuts + (n,)
    parts = [s[c[i]:c[i + 1]] for i in range(4)]
    good = True
    for p in parts:
        if len(p) > 1 and p[0] == '0':
            good = False
        if int(p) > 255:
            good = False
    if good:
        res.add('.'.join(parts))
res = sorted(res)
